commit 016475e137abe3f376652b526cb66f13cb1f3494
Author: Kale Aaron Pasch <kalepasch@gmail.com>
Date:   Fri Jul 10 01:40:07 2026 -0400

    test: add regression tests reproducing qafix-pareto-2080-07062319 dead-code failure

    Adds two structural tests that catch the original failure: fitPiecewiseLinear
    was a dead private function duplicating fitLinearModel's logic inside
    fitVendorGrid. The tests read module source to assert (1) fitPiecewiseLinear
    is absent, and (2) exactly one private fit helper (fitLinearModel) remains.
    Both tests would fail if the dead code were reintroduced.

    Co-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>
---
 tests/pricingGridReconstruction.test.js | 30 ++++++++++++++++++++++++++++++
 1 file changed, 30 insertions(+)

diff --git a/tests/pricingGridReconstruction.test.js b/tests/pricingGridReconstruction.test.js
index 990d941..3e1de1c 100644
--- a/tests/pricingGridReconstruction.test.js
+++ b/tests/pricingGridReconstruction.test.js
@@ -1,5 +1,8 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { fileURLToPath } from "node:url";
+import { join, dirname } from "node:path";
 import {
   fitVendorGrid,
   predictQuote,
@@ -8,6 +11,11 @@ import {
   detectReprice,
 } from "../server/utils/pricingGridReconstruction.js";

+const MODULE_SRC = readFileSync(
+  join(dirname(fileURLToPath(import.meta.url)), "../server/utils/pricingGridReconstruction.js"),
+  "utf8"
+);
+
 // ── Synthetic 3-tier grid for testing ──────────────────────────────────────────

 /**
@@ -489,3 +497,25 @@ test("CONSTRAINT: grid marked as consumer-only and never to be sold/fed-back to
   // (verified via module structure: no DB write, no network call, no side effects)
   assert.ok(typeof grid === "object", "grid is a plain object suitable only for analysis");
 });
+
+// ── Structural regression: no dead duplicate helpers ──────────────────────────
+// Reproduces qafix-pareto-2080-07062319: fitPiecewiseLinear was a dead private
+// function that duplicated the inline tier-fitting logic in fitVendorGrid.
+// This test fails if the dead code is reintroduced.
+
+test("regression: fitPiecewiseLinear dead function is absent from module source", () => {
+  assert.ok(
+    !MODULE_SRC.includes("fitPiecewiseLinear"),
+    "fitPiecewiseLinear must not exist in source (dead code removed in qafix-pareto-2080-07062319)"
+  );
+});
+
+test("regression: module source has exactly one internal fit helper (fitLinearModel)", () => {
+  const helpers = (MODULE_SRC.match(/^function fit\w+/gm) || []);
+  assert.equal(
+    helpers.length,
+    1,
+    `expected exactly 1 private fit helper (fitLinearModel), found: ${helpers.join(", ")}`
+  );
+  assert.ok(MODULE_SRC.includes("function fitLinearModel("), "the surviving helper is fitLinearModel");
+});

